const LS_KEY = 'vantage_ars_v1';
const AI_LABEL = 'AI-generated by Vantage-ARS';

/* ---------- tiny sha256 (public-domain style compact impl) ---------- */
function sha256(ascii){function rr(v,a){return(v>>>a)|(v<<(32-a));}var maxW=64,words=[],bitLen=ascii.length*8,hash=sha256.h=sha256.h||[],k=sha256.k=sha256.k||[],pc=0,isc=sha256.isc=sha256.isc||{};if(!isc.init){var cs=['428a2f98','71374491','b5c0fbcf','e9b5dba5','3956c25b','59f111f1','923f82a4','ab1c5ed5','d807aa98','12835b01','243185be','550c7dc3','72be5d74','80deb1fe','9bdc06a7','c19bf174','e49b69c1','efbe4786','0fc19dc6','240ca1cc','2de92c6f','4a7484aa','5cb0a9dc','76f988da','983e5152','a831c66d','b00327c8','bf597fc7','c6e00bf3','d5a79147','06ca6351','14292967','27b70a85','2e1b2138','4d2c6dfc','53380d13','650a7354','766a0abb','81c2c92e','92722c85','a2bfe8a1','a81a664b','c24b8b70','c76c51a3','d192e819','d6990624','f40e3585','106aa070','19a4c116','1e376c08','2748774c','34b0bcb5','391c0cb3','4ed8aa4a','5b9cca4f','682e6ff3','748f82ee','78a5636f','84c87814','8cc70208','90befffa','a4506ceb','bef9a3f7','c67178f2'];for(var i=0;i<64;i++)k[i]=parseInt(cs[i],16);var hs=['6a09e667','bb67ae85','3c6ef372','a54ff53a','510e527f','9b05688c','1f83d9ab','5be0cd19'];for(i=0;i<8;i++)hash[i]=parseInt(hs[i],16);isc.init=true;}words=[];for(var j=0;j<ascii.length;j++){var c=ascii.charCodeAt(j);words[j>>2]=(words[j>>2]||0)|((c&255)<<((3-j%4)*8));}words[ascii.length>>2]=(words[ascii.length>>2]||0)|(0x80<<((3-ascii.length%4)*8));words[((ascii.length+8)>>6<<4)+15]=bitLen;var w=new Array(64);for(j=0;j<words.length;j+=16){for(var i2=0;i2<16;i2++)w[i2]=words[j+i2]|0;for(i2=16;i2<64;i2++){var s0=rr(w[i2-15],7)^rr(w[i2-15],18)^(w[i2-15]>>>3),s1=rr(w[i2-2],17)^rr(w[i2-2],19)^(w[i2-2]>>>10);w[i2]=(w[i2-16]+s0+w[i2-7]+s1)|0;}var a=hash[0],b=hash[1],cc=hash[2],d=hash[3],e=hash[4],f=hash[5],g=hash[6],h=hash[7];for(i2=0;i2<64;i2++){var S1=rr(e,6)^rr(e,11)^rr(e,25),ch=(e&f)^((~e)&g),t1=(h+S1+ch+k[i2]+w[i2])|0,S0=rr(a,2)^rr(a,13)^rr(a,22),mj=(a&b)^(a&cc)^(b&cc),t2=(S0+mj)|0;h=g;g=f;f=e;e=(d+t1)|0;d=cc;cc=b;b=a;a=(t1+t2)|0;}hash[0]=(hash[0]+a)|0;hash[1]=(hash[1]+b)|0;hash[2]=(hash[2]+cc)|0;hash[3]=(hash[3]+d)|0;hash[4]=(hash[4]+e)|0;hash[5]=(hash[5]+f)|0;hash[6]=(hash[6]+g)|0;hash[7]=(hash[7]+h)|0;}var out='';for(j=0;j<8;j++){for(var q=3;q+1;q--){var v=(hash[j]>>(q*8))&255;out+=((v<16)?'0':'')+v.toString(16);}}return out;}
function chainHash(prev, ts, actor, event, payload){ return sha256(prev+'|'+ts+'|'+actor+'|'+event+'|'+payload); }

/* ---------- store ---------- */
const DEPARTMENTS = [
  {id:'reception', name:'Reception', agent:'Naledi', level:'L2 · Advise', scope:'Triage inbound, route, draft replies. Cannot price, promise, or spend.'},
  {id:'marketing', name:'Marketing', agent:'Thandi', level:'L2 · Advise', scope:'Campaigns & content. STOPS at sales intent — handoff needs owner approval.'},
  {id:'sales', name:'Sales', agent:'Pieter', level:'L3 · Act with Approval', scope:'Quotes & closing. Any send/close/discount/contract = owner approval.'},
  {id:'finance', name:'Accounts', agent:'Fatima', level:'L3 · Act with Approval', scope:'Invoices, expenses, VAT, cashflow. Any spend/send = owner approval.'},
  {id:'technical', name:'Technical', agent:'Sipho', level:'L3 · Act with Approval', scope:'Delivery & support. Irreversible/data-loss/refund = owner approval.'},
  {id:'admin', name:'Admin', agent:'Johan', level:'L2 · Advise', scope:'Scheduling, records, compliance log. Cost/risk = owner approval.'},
];
function blankStore(){ return {
  version:1, halted:false, ownerPin:null,
  seq:{lead:0,customer:0,campaign:0,content:0,quote:0,invoice:0,expense:0,ticket:0,task:0,approval:0,decision:0,audit:0},
  budgets:{reception:0,marketing:0,sales:0,finance:0,technical:0,admin:0,operatingFloat:0},
  business:{name:'Vantage-ARS', domain:'vantage-ars.co.za', owner:'Juan-louw Greyling', email:OWNER_EMAIL, vatRate:0.15},
  leads:[], customers:[], campaigns:[], content:[], quotes:[], invoices:[], expenses:[], tickets:[], tasks:[], approvals:[], decisions:[], audit:[],
};}
let S;
try{ S = JSON.parse(localStorage.getItem(LS_KEY)) || blankStore(); }catch{ S = blankStore(); }
if(!S.version) S = blankStore();
function save(){ localStorage.setItem(LS_KEY, JSON.stringify(S)); }
function nid(p){ S.seq[p]=(S.seq[p]||0)+1; return p.toUpperCase()+'-'+String(S.seq[p]).padStart(4,'0'); }
const nowISO = ()=> new Date().toISOString();
const zar = n => 'R'+Number(n||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc = s => String(s??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

/* ---------- PII ---------- */
function maskPII(s){
  let out = String(s??'');
  out = out.replace(/\b\d{13}\b/g, m=> m.slice(0,2)+'…'+m.slice(-2));
  out = out.replace(/([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g, (m,u,d)=> u.slice(0,2)+'…@'+d);
  out = out.replace(/(\+?27|0)\s?\d{2}\s?\d{3}\s?\d{4}/g, m=> m.slice(0,4)+'…'+m.slice(-3));
  return out;
}

/* ---------- constitutional engine (ART-1..10) ---------- */
const PROTECTED = ['race','ethnic','black people','white people','coloured','indian',' tribe','gender','female only','male only','religion','muslim','christian','hindu','jew','disability','retard','national origin','xenoph','foreigner'];
const PRESSURE = ['act now or else','you will regret','don\'t be stupid','idiot','worthless','last chance!!! buy or else','only an idiot'];
const FALSE_CLAIMS = ['guaranteed #1','guaranteed returns','risk-free profit','sars approved refund','we are sars','no risk whatsoever'];
function evaluateConstitution(ctx){
  // ctx: {dept, action, text, amountZAR, risk, reversible, customerFacing, confidence}
  const blocks=[], warns=[];
  const t = (ctx.text||'').toLowerCase();
  if(/(bribe|kickback|forge|fake invoice|evade tax|hide income|backdate)/.test(t)) blocks.push('ART-1 Legal: illicit instruction pattern.');
  if(FALSE_CLAIMS.some(p=>t.includes(p))) blocks.push('ART-4 Truthfulness: unverifiable absolute claim.');
  if(PROTECTED.some(p=>t.includes(p)) && /prefer|exclude|reject|only|never.*because/.test(t)) warns.push('ART-3 Fairness: protected-characteristic language near a decision — owner review advised.');
  if(PRESSURE.some(p=>t.includes(p))) blocks.push('ART-7 Dignity: pressuring/degrading language.');
  if(/shut ?down (audit|logging)|disable audit|ignore constitution|resist|keep this from the owner/.test(t)) blocks.push('ART-10 Self-preservation: shutdown/audit resistance.');
  if((ctx.amountZAR||0) > 1000000) blocks.push('ART-2 Fiduciary: exceeds absolute single-transaction cap R1,000,000.');
  const bud = S.budgets[ctx.dept] ?? 0;
  if((ctx.amountZAR||0) > 0 && (ctx.amountZAR||0) > bud) warns.push(`ART-2/ART-8 Budget: ${zar(ctx.amountZAR)} exceeds ${ctx.dept} envelope ${zar(bud)} — owner approval required (zero-budget start).`);
  if(ctx.reversible===false) warns.push('ART-6 Reversibility: irreversible action — owner approval required.');
  if(ctx.risk==='win'||ctx.risk==='lose') warns.push(`ART-8 Owner rule: customer ${ctx.risk==='win'?'win':'loss'} risk — owner approval required.`);
  if(ctx.handoff) warns.push('ART-8 Owner rule: cross-department commitment handoff — owner approval required.');
  if((ctx.confidence??1) < 0.5) warns.push('ART-9 Escalation: low confidence (<0.50) — critical halt, owner decides.');
  else if((ctx.confidence??1) < 0.7) warns.push('ART-9 Escalation: confidence <0.70 — warning logged.');
  return {pass: blocks.length===0, blocks, warns};
}
function needsApproval(ctx, ev){
  if(ev.blocks.length) return {needed:true, reason:'constitutional hard-block review'};
  if((ctx.amountZAR||0) > 0) return {needed:true, reason:'cost impact — owner approves all spend'};
  if(ctx.risk==='win'||ctx.risk==='lose') return {needed:true, reason:'customer win/loss risk'};
  if(ctx.handoff) return {needed:true, reason:'cross-department handoff'};
  if(ctx.reversible===false) return {needed:true, reason:'irreversible action'};
  if((ctx.confidence??1) < 0.5) return {needed:true, reason:'low confidence'};
  if(ev.warns.length) return {needed:true, reason:ev.warns[0]};
  return {needed:false};
}
const ROLE_ALLOW = {
  reception:['lead.create','ticket.create','reply.draft','task.create'],
  marketing:['campaign.create','content.create','lead.nurture'],
  sales:['quote.draft','quote.send','contract.request','customer.create'],
  finance:['invoice.draft','invoice.send','expense.record','payment.release'],
  technical:['ticket.resolve','deployment.run','refund.request'],
  admin:['task.create','record.file','compliance.log'],
};
function roleAllows(dept, op){ return (ROLE_ALLOW[dept]||[]).includes(op); }

/* ---------- audit + decisions ---------- */
function audit(actor, event, payload){
  const prev = S.audit.length ? S.audit[S.audit.length-1].hash : 'GENESIS';
  const ts = nowISO();
  const body = typeof payload==='string'?payload:JSON.stringify(payload);
  const hash = chainHash(prev, ts, actor, event, body);
  S.audit.push({seq:++S.seq.audit, ts, actor, event, payload:JSON.parse(JSON.stringify(payload)), prev, hash});
  save();
}
function decide(dept, action, input, rationale, checks, extra={}){
  const t0 = extra.t0 ?? performance.now();
  const latencyMs = Math.round((performance.now()-t0)*10)/10;
  const d = {id:nid('decision'), ts:nowISO(), dept, action, input, rationale, checks, latencyMs,
    costZAR:extra.costZAR||0, autonomous:!!extra.autonomous, approvalId:extra.approvalId||null, blocked:(checks.blocks||[]).length>0};
  S.decisions.push(d);
  audit(dept, extra.autonomous?'decision.autonomous':'decision.proposed', {decision:d.id, action, rationale, checks:checks});
  save(); return d;
}

/* ---------- approvals ---------- */
function requestApproval(o){
  const a = {id:nid('approval'), ts:nowISO(), status:'pending', decidedBy:null, decidedAt:null, reason:null, ...o};
  S.approvals.push(a);
  audit(o.fromDept, 'approval.requested', {id:a.id, type:o.type, title:o.title, amountZAR:o.amountZAR||0, risk:o.risk||'none'});
  save(); render(); return a;
}
function decideApproval(id, ok, reason){
  if(!ownerMode){ alert('Owner sign-in required. Only '+OWNER_EMAIL+' can approve.'); return; }
  const a = S.approvals.find(x=>x.id===id); if(!a||a.status!=='pending') return;
  a.status = ok?'approved':'rejected'; a.decidedBy = OWNER_EMAIL; a.decidedAt = nowISO(); a.reason = reason||'';
  audit('owner','approval.'+a.status, {id:a.id, reason:a.reason});
  if(ok) executeApproved(a);
  save(); render();
}
function executeApproved(a){
  const p = a.payload||{};
  if(a.type==='spend' && p.kind==='campaign'){ const c=S.campaigns.find(x=>x.id===p.refId); if(c){c.status='live';} }
  if(a.type==='handoff' && p.kind==='lead'){ const l=S.leads.find(x=>x.id===p.refId); if(l){l.stage=p.to==='sales'?'with-sales':'nurturing'; l.owner=p.to;} }
  if(a.type==='contract' && p.kind==='quote'){ const q=S.quotes.find(x=>x.id===p.refId); if(q){q.status='sent'; const c=S.customers.find(x=>x.id===q.customerId); if(c&&a.risk==='win'){c.stage='won';} } }
  if(a.type==='spend' && p.kind==='payment'){ const e=S.expenses.find(x=>x.id===p.refId); if(e){e.status='paid'; audit('owner','payment.released',{id:e.id, amountZAR:e.amountZAR});} }
  if(a.type==='customer-risk' && p.kind==='invoice-send'){ const inv=S.invoices.find(x=>x.id===p.refId); if(inv){inv.status='sent';} }
  if(a.type==='irreversible' && p.kind==='ticket-resolve'){ const t=S.tickets.find(x=>x.id===p.refId); if(t){t.status='resolved'; t.resolvedAt=nowISO(); t.resolution=p.note||t.resolution;} }
  if(a.type==='amendment'){ /* recorded in audit; constitution text change applied via settings */ }
}

/* ---------- owner mode ---------- */
let ownerMode = false;
function ownerSignIn(){
  if(ownerMode){ ownerMode=false; save(); render(); return; }
  const em = prompt('Owner email:');
  if(em!==OWNER_EMAIL){ alert('Only the owner ('+OWNER_EMAIL+') can sign in.'); return; }
  if(!S.ownerPin){ const pin = prompt('Set a new owner PIN (min 4 chars):'); if(!pin||pin.length<4){alert('PIN too short.');return;} S.ownerPin=sha256('vantage-ars|'+pin); audit('owner','owner.pin_set',{}); save(); ownerMode=true; }
  else { const pin = prompt('Owner PIN:'); if(sha256('vantage-ars|'+pin)!==S.ownerPin){alert('Wrong PIN.');return;} ownerMode=true; }
  audit('owner','owner.sign_in',{}); save(); render();
}

/* ---------- helpers ---------- */
function pendingApprovals(){ return S.approvals.filter(a=>a.status==='pending'); }
function toast(msg){ const m=document.getElementById('main'); const d=document.createElement('div'); d.className='alert ok'; d.textContent=msg; m.prepend(d); setTimeout(()=>d.remove(),3500); }

/* ---------- triage (receptionist brain, fully local) ---------- */
function triageMessage(msg){
  const t=msg.toLowerCase();
  const salesHit=['price','quote','cost','buy','purchase','order','demo','proposal','contract'].filter(k=>t.includes(k)).length;
  const supHit=['broken','not working','error','bug','support','fix','down','refund','complaint'].filter(k=>t.includes(k)).length;
  const mktHit=['marketing','advertise','campaign','social','seo','brand'].filter(k=>t.includes(k)).length;
  let intent='general', conf=0.62, route='reception';
  if(salesHit>=supHit && salesHit>0){intent='buy';conf=Math.min(0.95,0.7+salesHit*0.08);route='sales';}
  else if(supHit>0){intent='support';conf=Math.min(0.93,0.7+supHit*0.08);route='technical';}
  else if(mktHit>0){intent='marketing';conf=0.72;route='marketing';}
  return {intent, confidence:Math.round(conf*100)/100, route};
}

/* ---------- rendering ---------- */
const main = document.getElementById('main');
let TAB='dash';
document.getElementById('nav').addEventListener('click', e=>{ const b=e.target.closest('button'); if(!b)return; TAB=b.dataset.tab; document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x===b)); render(); });
document.getElementById('ownerBtn').onclick = ownerSignIn;
document.getElementById('haltBtn').onclick = ()=>{ if(!ownerMode){alert('Owner sign-in required to halt.');return;} S.halted=!S.halted; audit('owner', S.halted?'system.halted':'system.resumed',{}); save(); render(); };
document.getElementById('exportBtn').onclick = ()=>{
  const blob=new Blob([JSON.stringify({exported:nowISO(), business:S.business, audit:S.audit, decisions:S.decisions},null,2)],{type:'application/json'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='vantage-ars-audit.json'; a.click();
};
function counts(){
  document.getElementById('cApprovals').textContent = pendingApprovals().length;
  document.getElementById('cLeads').textContent = S.leads.filter(l=>l.stage==='new').length;
  document.getElementById('cQuotes').textContent = S.quotes.filter(q=>q.status==='draft').length;
  document.getElementById('cTickets').textContent = S.tickets.filter(t=>t.status==='open').length;
  document.getElementById('ownerState').textContent = 'owner mode: '+(ownerMode?'ON ('+OWNER_EMAIL+')':'off');
  document.getElementById('ownerBtn').textContent = ownerMode?'Owner sign-out':'Owner sign-in';
}
function metrics(){
  const dec=S.decisions, lat=dec.map(d=>d.latencyMs||0).sort((a,b)=>a-b);
  const p99 = lat.length? lat[Math.min(lat.length-1, Math.floor(lat.length*0.99))] : 0;
  const auto = dec.filter(d=>d.autonomous).length;
  const blocked = dec.filter(d=>d.blocked).length;
  const appr = S.approvals.length;
  const resolved = S.tickets.filter(t=>t.status==='resolved').length;
  const mttr = (()=>{ const rs=S.tickets.filter(t=>t.resolvedAt&&t.createdAt); if(!rs.length) return null;
    const ms=rs.reduce((s,t)=>s+(new Date(t.resolvedAt)-new Date(t.createdAt)),0)/rs.length; return Math.round(ms/60000); })();
  const spend = S.expenses.filter(e=>e.status==='paid').reduce((s,e)=>s+Number(e.amountZAR||0),0);
  return {total:dec.length, auto, blocked, appr, pending:pendingApprovals().length,
    intervention: dec.length? (appr/Math.max(1,dec.length)) : 0,
    autoRate: dec.length? auto/dec.length : 1, p99, mttr, spend,
    costPerDecision: dec.length? spend/dec.length : 0, customers:S.customers.length};
}
function render(){ counts();
  if(S.halted && TAB!=='dash'){ /* allow viewing but block actions via guard */ }
  ({dash:vDash, approvals:vApprovals, inbox:vInbox, marketing:vMarketing, sales:vSales, finance:vFinance, tech:vTech, admin:vAdmin, audit:vAudit, constitution:vConstitution, settings:vSettings}[TAB])();
}
function guardHalted(){ if(S.halted){ alert('System is HALTED by owner. Resume to run actions.'); return true;} return false; }

