/* ----- APPROVALS ----- */
function vApprovals(){
  const list=[...S.approvals].reverse();
  main.innerHTML = `<h2>Approvals — owner gate</h2>
  <div class="small mut">Only <b>${esc(OWNER_EMAIL)}</b> can decide. Rule: anything that <b>costs money</b>, <b>risks losing a customer</b>, or <b>wins a customer</b> (quote, contract, invoice-send, handoff) stops here. ${ownerMode?'<span class="badge approved">owner signed in</span>':'<span class="badge pending">owner sign-in required to decide</span>'}</div>
  ${list.length?'':'<div class="card" style="margin-top:12px">No approvals yet. Create work in any department — gated actions will appear here automatically.</div>'}
  ${list.map(a=>`<div class="card" style="margin-top:10px"><div class="row"><b>${esc(a.title)}</b><span class="badge ${a.status}">${a.status}</span><span class="badge">${esc(a.type)}</span>${a.amountZAR?`<span class="badge">${zar(a.amountZAR)}</span>`:''}${a.risk&&a.risk!=='none'?`<span class="badge blocked">customer-${esc(a.risk)} risk</span>`:''}</div>
    <div class="small mut">${a.id} · from ${esc(a.fromDept)}${a.toDept?' → '+esc(a.toDept):''} · ${esc(a.ts)}</div>
    <div class="small" style="margin-top:6px">${esc(a.detail||'')}</div>
    ${a.decidedAt?`<div class="small mut">Decided ${a.status} by ${esc(a.decidedBy)} at ${esc(a.decidedAt)} — ${esc(a.reason||'')}</div>`:''}
    ${a.status==='pending'?`<div class="toolbar"><button class="primary" data-ok="${a.id}">Approve &amp; execute</button><button class="danger" data-no="${a.id}">Reject</button></div>`:''}
  </div>`).join('')}`;
  main.querySelectorAll('[data-ok]').forEach(b=>b.onclick=()=>{const r=prompt('Approval note (optional):')||'';decideApproval(b.dataset.ok,true,r);});
  main.querySelectorAll('[data-no]').forEach(b=>b.onclick=()=>{const r=prompt('Rejection reason (recorded):')||'';decideApproval(b.dataset.no,false,r);});
}

/* ----- INBOX / RECEPTION ----- */
function vInbox(){
  main.innerHTML = `<h2>Reception — Naledi <span class="badge">L2 · Advise</span> <span class="badge ai">${AI_LABEL}</span></h2>
  <div class="small mut">Naledi triages every inbound message locally (no external AI calls, zero cost): intent, confidence, route. Sales-intent leads halt for your approval before Sales may touch them (marketing/sales boundary).</div>
  <div class="card" style="margin-top:10px"><h3>Log inbound enquiry (phone / email / walk-in / web)</h3>
    <div class="form-grid"><div><label>Name / company</label><input id="fName" placeholder="e.g. Karabo Mokoena, Acme Foods"></div>
    <div><label>Channel</label><select id="fChan"><option>phone</option><option>email</option><option>walk-in</option><option>web</option><option>whatsapp</option></select></div></div>
    <label>Contact (email or phone)</label><input id="fContact" placeholder="name@example.co.za / 082 ...">
    <label>Message (their words)</label><textarea id="fMsg" placeholder="What did they ask for?"></textarea>
    <div class="toolbar"><button class="primary" id="triageBtn">Triage &amp; file</button></div></div>
  <h3>Leads (${S.leads.length})</h3>
  <div class="card"><table><tr><th>ID</th><th>Who</th><th>Intent / route</th><th>Stage</th><th>Message</th><th></th></tr>
  ${[...S.leads].reverse().map(l=>`<tr><td class="mono">${l.id}</td><td>${esc(l.name)}<br><span class="small mut">${esc(maskPII(l.contact))} · ${esc(l.channel)}</span></td>
    <td><span class="badge">${esc(l.intent)}</span> <span class="badge">conf ${l.confidence}</span><br><span class="small mut">→ ${esc(l.owner)}</span></td>
    <td><span class="badge">${esc(l.stage)}</span></td><td class="small">${esc(maskPII(l.message))}<br><span class="mut">${AI_LABEL} triage note: ${esc(l.note||'')}</span></td>
    <td>${l.stage==='new'?`<button data-nur="${l.id}">Nurture (marketing)</button>`:''}</td></tr>`).join('')||'<tr><td colspan=6 class=mut>No leads yet — log the first real enquiry above.</td></tr>'}</table></div>`;
  document.getElementById('triageBtn').onclick = ()=>{
    if(guardHalted())return;
    const t0=performance.now();
    const name=document.getElementById('fName').value.trim(), contact=document.getElementById('fContact').value.trim(),
      channel=document.getElementById('fChan').value, message=document.getElementById('fMsg').value.trim();
    if(!name||!message){alert('Name and message are required.');return;}
    if(!roleAllows('reception','lead.create')){alert('Role block.');return;}
    const tr=triageMessage(message);
    const ev=evaluateConstitution({dept:'reception',action:'lead.create',text:message,risk:tr.route==='sales'?'win':'none',reversible:true,confidence:tr.confidence});
    if(ev.blocks.length){ decide('reception','lead.create (BLOCKED)',{name,message},'Blocked: '+ev.blocks.join(' '),ev,{t0}); alert('Blocked by constitution: '+ev.blocks.join(' ')); return; }
    const lead={id:nid('lead'),createdAt:nowISO(),name,contact,channel,message,intent:tr.intent,confidence:tr.confidence,owner:tr.route,stage:'new',note:`intent=${tr.intent} route=${tr.route}`};
    const gate=needsApproval({risk:tr.route==='sales'?'win':'none',handoff:tr.route==='sales',confidence:tr.confidence,amountZAR:0,reversible:true},ev);
    if(gate.needed && tr.route==='sales'){
      S.leads.push(lead);
      const d=decide('reception','lead.create → handoff gated',{lead:lead.id,tr},`Filed lead ${lead.id}; sales intent → HALT for owner before Sales may act.`,ev,{t0});
      requestApproval({fromDept:'reception',toDept:'sales',type:'handoff',risk:'win',title:`Sales handoff: ${name}`,detail:`Naledi triaged "${message.slice(0,140)}" as buying intent (conf ${tr.confidence}). Approve to move ${lead.id} to Sales (Pieter).`,payload:{kind:'lead',refId:lead.id,to:'sales'}});
      toast('Lead filed. Sales handoff sent to Approvals.'); return;
    }
    S.leads.push(lead);
    decide('reception','lead.create',{lead:lead.id,tr},`Filed ${lead.id} → ${tr.route} (conf ${tr.confidence}).`,ev,{t0,autonomous:true});
    save(); render(); toast('Lead '+lead.id+' filed.');
  };
  main.querySelectorAll('[data-nur]').forEach(b=>b.onclick=()=>{
    if(guardHalted())return; const l=S.leads.find(x=>x.id===b.dataset.nur);
    const ev=evaluateConstitution({dept:'reception',action:'handoff',text:l.message,risk:'none',handoff:true,reversible:true,confidence:0.8});
    decide('reception','lead.nurture.request',{lead:l.id},'Nurture requested → owner handoff.',ev,{});
    requestApproval({fromDept:'reception',toDept:'marketing',type:'handoff',risk:'none',title:`Nurture: ${l.name}`,detail:`Move ${l.id} to Marketing (Thandi) for nurture.`,payload:{kind:'lead',refId:l.id,to:'marketing'}});
  });
}

