    const inv={id:nid('invoice'),createdAt:nowISO(),customerId,desc,amountZAR:total,status:'draft'};
    S.invoices.push(inv); decide('finance','invoice.draft',{invoice:inv.id},`Invoice ${inv.id} drafted ${zar(total)}.`,ev,{t0,autonomous:true});
    const ev2=evaluateConstitution({dept:'finance',action:'invoice.send',text:desc,risk:'win',reversible:false,confidence:0.85,customerFacing:true});
    decide('finance','invoice.send.request',{invoice:inv.id},'Sending invoice wins/commits customer → owner gate.',ev2,{});
